package mrpapermoon.whisper.ui.widgetimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.BoxScopeimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.drawWithCacheimport androidx.compose.ui.graphics.ColorFilterimport androidx.compose.ui.graphics.ImageBitmapimport androidx.compose.ui.res.imageResourceimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.Dpimport androidx.compose.ui.unit.IntOffsetimport androidx.compose.ui.unit.IntSizeimport androidx.compose.ui.unit.dpimport mrpapermoon.whisper.Rimport mrpapermoon.whisper.ui.theme.WhisperColorsimport mrpapermoon.whisper.ui.theme.WhisperTheme@Composablefun BrandBackground(modifier: Modifier = Modifier, padding: Dp = 0.dp, content: @Composable BoxScope.() -> Unit) {	val colorResource = WhisperColors.accent_50	val imageBitmap = ImageBitmap.imageResource(id = R.drawable.istockphoto_1490468047_612x612)	val tint = ColorFilter.tint(WhisperColors.primary_200)	val ratio = imageBitmap.height.toFloat() / imageBitmap.width	Box(		modifier = modifier			.fillMaxSize()			.drawWithCache {				// TODO: не забыть подогнать размеры изображения под экран, если изображение больше				val pxPadding = padding.toPx()				val width = (size.width - (2 * pxPadding)).coerceAtLeast(0f)				val height = (size.height - (2 * pxPadding)).coerceAtLeast(0f)				onDrawBehind {					drawRect(color = colorResource)					val dstHeight = width * ratio					val dstTop = (height - dstHeight) / 3					if (width > 0f && dstHeight > 0f) {						drawImage(							image = imageBitmap,							dstSize = IntSize(width.toInt(), dstHeight.toInt()),							dstOffset = IntOffset(pxPadding.toInt(), dstTop.toInt()),							colorFilter = tint						)					}				}			}			.padding(padding),		content = content,	)}@Preview@Composablefun SplashScreenPreview() {	WhisperTheme {		BrandBackground {}	}}